Translate("ruRU", "durotar", {
	title = "Дуротар",
	sections = {
		{
			title = "Обзор",
			text = [=[Дуротар — родина {link:orcs}орк{/link}ов, красный изломанный край на восточном берегу {link:kalimdor}Калимдора{/link}. Его почва суха и растрескалась, его каньоны остры, а солнце палит его без пощады. Орки выбрали его с радостью, ибо его суровая красота напоминает им мир, который они потеряли. Здесь вождь {link:thrall}Тралл{/link} воздвиг свою столицу, {link:orgrimmar}Оргриммар{/link}, и здесь молодых воинов {link:horde}Орды{/link} испытывают, прежде чем послать в большой мир. Мирной эту землю можно назвать лишь по имени. Враги следят за ней с моря, из каньонов и из теней ее собственных пещер.]=],
		},
		{
			title = "Истоки",
			text = [=[До прихода {link:orcs}орк{/link}ов эти земли считались частью {link:the-barrens}Степей{/link}, и {link:quilboar}свинобразы{/link} племени Игл{link:ogres}огр{/link}ивых бродили по ним свободно. После {link:battle-of-mount-hyjal}битвы за гору Хиджал{/link} {link:thrall}Тралл{/link} повел свой народ на восток, к побережью, и занял землю между Рекой Строптивой и морем. Он назвал ее Дуротаром в честь своего отца Дуротана, который был вождем клана Северного Волка. {link:tauren}Таурены{/link} и {link:darkspear-trolls}тролли Черного Копья{/link} отдали свои силы новой державе, и орки вытеснили Иглогривых отовсюду, кроме западных окраин.]=],
		},
		{
			title = "Наши дни",
			text = [=[Дуротар — сердце новой Орды. Но мир в нем хрупок. {link:humans}Люди{/link} {link:kul-tiras}Кул Тираса{/link} все еще удерживают руины Крепости Тирагард на восточном берегу. Знахарь {link:zalazane}Залазан{/link} правит Островами Эха с помощью темного вуду. {link:razormane-quilboar}Иглогривые{/link} напирают с запада, {link:centaurs}кентавры{/link} клана {link:kolkar-centaurs}Колкар{/link} строят козни на своем утесе, а {link:harpies}гарпии{/link} стаи Пыльного Ветра нападают на караваны. Хуже всего то, что сектанты {link:burning-blade}Пылающего Клинка{/link} прячутся в пещерах Дуротара, у самых ворот столицы. В последнее время вдоль северного берега видели даже {link:naga}наг{/link}.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}{link:orcs}Орки{/link}.{/b} Они возделывают твердую землю, несут дозор на Колючем Холме и обучают молодых в Долине Испытаний.
• {b}{link:trolls}Тролли{/link} Черного Копья.{/b} Изгнанные со своих островов, они построили рыбацкую деревню на южном берегу и ждут дня, когда смогут вернуться домой.
• {b}Гоблины.{/b} Торговцы из {link:ratchet}Кабестан{/link}а водят караваны по дорогам.
• {b}{link:razormane-quilboar}Свинобразы племени Иглогривых{/link}.{/b} Они цепляются за свои терновые лагеря на западе и клянутся вернуть землю.
• {b}{link:humans}Люди{/link} {link:kul-tiras}Кул Тирас{/link}а.{/b} Моряки и морские пехотинцы, которые служат памяти своего мертвого адмирала.
• {b}{link:burning-blade}Пылающий Клинок{/link}.{/b} Демонопоклонники, прячущиеся в пещерах.]=],
		},
		{
			title = "История",
			text = [=[• {b}Высадка.{/b} После войны с {link:burning-legion}Пылающим Легионом{/link} {link:orcs}орк{/link}и построили {link:orgrimmar}Оргриммар{/link} и начали покорять землю вокруг него.
• {b}Война адмирала.{/b} Вскоре после этого верховный адмирал {link:daelin-proudmoore}Делин Праудмур{/link} отплыл из {link:kul-tiras}Кул Тирас{/link}а с большим флотом, решив покончить с орками. Его люди возвели на берегу {link:tiragarde-keep}Крепость Тирагард{/link}. Крепость пала, а сам адмирал погиб перед стенами {link:theramore-isle}Терамор{/link}а.
• {b}{link:illidan-stormrage}Предатель{/link} с островов.{/b} {link:darkspear-trolls}Племя Черного Копья{/link} поселилось на Островах Эха, но один из его же знахарей, {link:zalazane}Залазан{/link}, обратил свою магию против него и прогнал свободных троллей на материк.]=],
		},
		{
			title = "Предания красной земли",
			text = [=[• Будущие шаманы Орды пьют священный напиток, который зовется саптой, у Священного Камня, высоко над Долиной Испытаний, и там предстают перед духом земли.
• Обломки флота, который привел Праудмур, до сих пор лежат на мелководье к востоку от Крепости Тирагард. {link:orcs}Орки{/link} Колючего Холма посылают пловцов искать в них орудия людей.
• Одна мать на Ферме Тор'кренов много дней ждала сына, который ушел охотиться на кроколисков Реки Строптивой. Он не вернулся.]=],
		},
	},
})

Translate("ruRU", "valley-of-trials", {
	title = "Долина Испытаний",
	sections = {
		{
			title = "Обзор",
			text = [=[Долина Испытаний лежит на юго-западе {link:durotar}Дуротар{/link}а, окруженная красными скалами. Это место, где {link:horde}Орда{/link} испытывает своих бойцов. Молодые {link:orcs}орк{/link}и и тролли приходят сюда, чтобы встретить своих первых врагов: кабанов на дне долины, скорпидов северных склонов и чудовищного скорпида по имени Саркот. Наставники Орды держат лагерь в пещере, известной как Логово. Батраки рубят немногие деревья долины на бревна, когда не спят. В последнее время в долине стало опаснее, ибо {link:burning-blade}Пылающий Клинок{/link} устроил себе грот в пещерах ее северной стены.]=],
		},
	},
})

Translate("ruRU", "burning-blade-coven", {
	title = "Грот Пылающего Клинка",
	sections = {
		{
			title = "Обзор",
			text = [=[Грот Пылающего Клинка — пещера в скалах к северу от Долины Испытаний. Когда-то рудокопы искали в ней руду. Теперь ее заняли сектанты {link:burning-blade}Пылающего Клинка{/link}, и их мелкие демоны, мерзкие прислужники, высыпают из ее устья в долину. В глубине, среди залов с падающей водой, чернокнижник {link:yarrog-baneshadow}Яррог Гибельная Тень{/link} стережет медальон темной силы. Грот невелик, но само его присутствие так близко к месту, где {link:horde}Орда{/link} испытывает своих бойцов, — предостережение о том, что культ дотягивается дальше, чем кому-либо хотелось бы.]=],
		},
	},
})

Translate("ruRU", "spirit-rock", {
	title = "Священный Камень",
	sections = {
		{
			title = "Обзор",
			text = [=[Священный Камень стоит в холмах высоко над Долиной Испытаний, в конце узкой тропы, которая зовется Потайной тропой. Для шаманов Орды это святая земля. Здесь молодые, желающие идти путем шамана, пьют напиток сапта, который связывает дух со {link:elements}стихиями{/link}, и здесь они впервые видят духа земли собственными глазами. Обряд должен быть совершен в святом месте, и нигде больше. Мало кто, кроме шаманов, когда-либо поднимается по Потайной тропе.]=],
		},
	},
})

Translate("ruRU", "razor-hill", {
	title = "Колючий Холм",
	sections = {
		{
			title = "Обзор",
			text = [=[Колючий Холм — перекресток {link:durotar}Дуротар{/link}а. Его дороги идут на север в {link:orgrimmar}Оргриммар{/link}, на юг в Долину Испытаний и Деревню Сен'джин и на запад, через реку, в {link:burning-steppes}Степи{/link}. Это город солдат. Из его казарм {link:gar-thok}Гар'Ток{/link} командует обороной края, а {link:orgnil-soulscar}Оргнил Шрам Души{/link} охотится на сектантов Пылающего Клинка. Старый воин хранит сигнальный рог на сторожевой башне над городом. Он трубит в него реже, чем прежде, и рад этому.]=],
		},
	},
})

Translate("ruRU", "sen-jin-village", {
	title = "Деревня Сен'джин",
	sections = {
		{
			title = "Обзор",
			text = [=[Деревня Сен'джин — дом свободных {link:darkspear-trolls}троллей Черного Копья{/link} на южном берегу {link:durotar}Дуротар{/link}а. {link:trolls}Тролли{/link} построили ее после того, как их изгнали с Островов Эха, и назвали в честь вождя Сен'джина, который отдал жизнь, чтобы его народ мог последовать за {link:orcs}орк{/link}ами в новую землю. Это деревня хижин и рыбацких причалов. Ее старейшины — знахари и алхимики, ее молодые — охотники, а ее укротители ящеров растят зверей с диких островов. С ее берега троллям видны острова, которые они потеряли.]=],
		},
	},
})

Translate("ruRU", "echo-isles", {
	title = "Острова Эха",
	sections = {
		{
			title = "Обзор",
			text = [=[Острова Эха лежат у юго-восточного побережья {link:durotar}Дуротар{/link}а. Им предназначалось стать новым домом племени Черного Копья. Теперь они принадлежат знахарю {link:zalazane}Залазан{/link}у, который держит троллей островов в рабстве своими проклятиями. Его рабы бродят среди хижин, а его груды джу-джу отравляют ток магии по всей земле. В джунглях охотятся ящеры Окровавленного Когтя и полосатые тигры. На самом большом острове круг черепов держит в плену духов троллей, бросивших ему вызов.]=],
		},
	},
})

Translate("ruRU", "tiragarde-keep", {
	title = "Крепость Тирагард",
	sections = {
		{
			title = "Обзор",
			text = [=[Крепость Тирагард стоит на восточном берегу {link:durotar}Дуротар{/link}а. Ее возвели моряки, которых привел адмирал {link:daelin-proudmoore}Делин Праудмур{/link}, когда их флот пришел уничтожить Орду. {link:orcs}Орки{/link} взяли крепость и разбили ее стены. Но после смерти адмирала запасной отряд под началом лейтенанта {link:archbishop-benedictus}Бенедикт{/link}а вернулся и вновь укрепил руины. Морские пехотинцы {link:kul-tiras}Кул Тираса{/link} по-прежнему поднимают там свое знамя. В обломках вокруг крепости лежит оружие орков, павших при первом штурме, и их родичи хотят, чтобы ему воздали почести.]=],
		},
	},
})

Translate("ruRU", "skull-rock", {
	title = "Скала Черепа",
	sections = {
		{
			title = "Обзор",
			text = [=[Скала Черепа — пещера в горах к востоку от ворот {link:orgrimmar}Оргриммар{/link}а. Это логово {link:burning-blade}Пылающего Клинка{/link}. Сектанты внутри совершают гнусные обряды и жгут собственную плоть обжигающими ошейниками, которые привязывают их к демонической силе. Их хозяин в пещере — чернокнижник {link:gazz-uz}Газз'уз{/link}, который подчиняется голосу, говорящему через подвеску пылающей тени. То, что культ может прятаться так близко к стенам вождя, тревожит каждого солдата Орды.]=],
		},
	},
})

Translate("ruRU", "drygulch-ravine", {
	title = "Сухая лощина",
	sections = {
		{
			title = "Обзор",
			text = [=[Каньон Колючего Ветра прорезает холмы между Колючим Холмом и {link:orgrimmar}Оргриммар{/link}ом, а за пещерой на его восточной стороне лежит скрытое ущелье — Сухая лощина. И то и другое принадлежит {link:harpies}гарпиям{/link} стаи Пыльного Ветра. Они бросаются сверху на гоблинские караваны на дороге, уносят их товары и копят их в своих гнездах на скалах. Сильнейшие из стаи стерегут свои яйца в лощине. Некоторые ведьмы гарпий начали баловаться странной магией бури.]=],
		},
	},
})

Translate("ruRU", "thunder-ridge", {
	title = "Громовой хребет",
	sections = {
		{
			title = "Обзор",
			text = [=[Громовой хребет — лесистое ущелье на северо-западе {link:durotar}Дуротар{/link}а, к югу от {link:orgrimmar}Оргриммар{/link}а. Свое имя оно получило от громовых ящеров, которые по нему бродят, — {link:ogres}огр{/link}омных зверей, чьи тела несут заряд молнии. Гоблин-чернокнижник Физзл Темная Буря разбил там лагерь с сектантами Пылающего Клинка, и они сеют хаос среди деревьев. {link:orcs}Орки{/link} охотятся на ящеров ради шкур, которыми кроют крыши растущей столицы. Самого могучего из них зовут Халикор, и его копыто — трофей, которым стоит похвалиться.]=],
		},
	},
})

Translate("ruRU", "kolkar-crag", {
	title = "Утес Колкара",
	sections = {
		{
			title = "Обзор",
			text = [=[Утес Колкара — скалистое ущелье на юге {link:durotar}Дуротар{/link}а, к западу от Деревни Сен'джин. {link:centaurs}Кентавры{/link} клана {link:kolkar-centaurs}Колкар{/link} устроили в нем свой лагерь. Они совершают набеги по ночам, а их полководец, Колканис, составил планы удара по {link:orcs}орк{/link}ам и троллям края. Один тролль, разведчик Орды, как-то прокрался на утес и прочел эти планы собственными глазами. Другие, кто пытался разведать утес в одиночку, не всегда выходили обратно.]=],
		},
	},
})

Translate("ruRU", "razormane-grounds", {
	title = "Земли Иглогривых",
	sections = {
		{
			title = "Обзор",
			text = [=[Земли Иглогривых лежат на западе {link:durotar}Дуротар{/link}а, где суша спускается к Реке Строптивой. Здесь {link:quilboar}свинобразы{/link} племени Игл{link:ogres}огр{/link}ивых держат свои терновые лагеря. Они владели большей частью Дуротара до прихода {link:orcs}орк{/link}ов и так и не смирились с его потерей. Дочиста обглоданные кости усеивают землю вокруг их терний. Их геоманты взывают к земле, а их боевая стража защищает лагеря с яростью, рожденной уязвленной гордостью. Орки Колючего Холма поклялись выгнать их из Дуротара, а после этого, быть может, и из {link:kalimdor}Калимдор{/link}а.]=],
		},
	},
})

Translate("ruRU", "darkspear-islands", {
	title = "Острова Черного Копья",
	sections = {
		{
			title = "Обзор",
			text = [=[Острова Черного Копья лежат у побережья {link:durotar}Дуротар{/link}а, и их бьют бури открытого моря. {link:trolls}Тролли{/link} считают их священными, ибо их духи там сильны, и племя Черного Копья собирается на них для своих обрядов. Теперь {link:alliance}Альянс{/link} ищет опору на этих островах, близ берегов родины {link:orcs}орк{/link}ов. {link:darkspear-trolls}Племя Черного Копья{/link} и его союзники из {link:horde}Орды{/link} не дадут ему остаться. Среди руин, лагеря, старой башни и бухты с разбитыми кораблями две стороны бьются за власть над островами и за священную реликвию племени.]=],
		},
	},
})

