	allegiance = "Нет",
	sections = {
		{
			title = "Обзор",
			text = [=[Залазан был когда-то знахарем {link:darkspear-trolls}племени Черного Копья{/link}, одаренным учеником, который помогал мастеру Гадрину обучать жрецов и магов племени. Силы, которые он вызвал, свели его с ума. Он проклял {link:echo-isles}Острова Эха{/link}, поработил своими чарами многих из собственного народа, а остальных прогнал через воду на материк. Теперь он правит островами как их хозяин и посылает своих зачарованных слуг через воду распространять его проклятие.]=],
		},
		{
			title = "Значение",
			text = [=[Залазан — причина того, что у племени Черного Копья нет своего дома. Каждый зачарованный тролль, что бродит по его островам, — рана в сердце племени.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он поработил троллей Островов Эха и прогнал свободных троллей Черного Копья в Деревню Сен'джин.
• Он посылает своих зачарованных троллей на материк, чтобы затянуть под свою власть еще больше их сородичей.
• Он заключает духов мертвых в черепа и в связующие подвески.
• Он отравляет ток магии в {link:durotar}Дуротар{/link}е своими грудами джу-джу.]=],
		},
	},
	chapters = {
		{
			title = "Круг черепов",
			hint = [=[Верните череп брата, которого потерял Гадрин, с острова, где правит Залазан.]=],
			text = [=[На самом большом острове Залазан держит круг силы, обнесенный черепами троллей, которых он убил. Их духи не могут уйти. Среди них был Миншина, брат мастера Гадрина, и он взывал к брату во снах до того дня, когда его череп принесли домой.]=],
		},
		{
			title = "Голова мастера проклятий",
			hint = "Принесите голову знахаря мастеру Гадрину.",
			text = [=[Знахарь пал среди своих хижин, и его голову отнесли в Деревню Сен'джин. В ту ночь тролли деревни спали спокойно. Но его проклятие по-прежнему лежит на островах, и племя Черного Копья не вернулось в свой дом.]=],
		},
	},
	mentions = {
		{ text = "Груды джу-джу" },
		{ text = "Заноза в шее, связующие подвески" },
		{ text = "Забытые идолы лоа" },
	},
	bonds = {
		{ id = "master-gadrin", name = "мастер Гадрин", note = "его бывший учитель" },
		{ id = "vol-jin", name = "Вол'джин", note = "вождь племени, которое он предал" },
	},
})

