Translate("ruRU", "daelin-proudmoore", {
	title = "Делин Праудмур",
	subtitle = "Верховный адмирал Кул Тираса",
	allegiance = "Кул Тирас · Дом Праудмуров",
	aliases = { "Делин", "адмирал Праудмур" },
	sections = {
		{
			title = "Обзор",
			text = [=[Делин Праудмур был лорд-адмиралом {link:kul-tiras}Кул Тираса{/link}, и его дочь — {link:jaina-proudmoore}Джайна Праудмур{/link}. Во {link:second-war}Вторую войну{/link} его флоты владели морями ради {link:alliance}Альянса{/link}, и он стал одним из великих героев людей. Он так и не простил {link:orcs}орк{/link}ам той войны. Когда он узнал, что они поселились на берегах {link:kalimdor}Калимдора{/link}, он пришел с армадой, чтобы их уничтожить, и погиб, пытаясь это сделать.]=],
		},
		{
			title = "Значение",
			text = [=[Его война была первой большой угрозой молодой державе {link:durotar}Дуротар{/link}а. Его смерть провела черту между отцом и дочерью и между двумя взглядами на {link:orcs}орк{/link}ов: как на народ, который может измениться, или как на чудовищ, которые не изменятся никогда. Его люди до сих пор удерживают {link:tiragarde-keep}Крепость Тирагард{/link} от его имени.]=],
		},
		{
			title = "Адмирал Альянса",
			text = [=[{link:kul-tiras}Кул Тирас{/link} был королевством моряков, и дом Праудмуров водил его флоты. Когда {link:horde}Орда{/link} двинулась на север после {link:first-war}Первой войны{/link}, Делин привел свой флот в {link:alliance}Альянс{/link} {link:lordaeron}Лордерона{/link}. Его корабли бились с флотами {link:orcs}орк{/link}ов в открытом море и возили войска Альянса от берега к берегу. Кул Тирас дорого заплатил кораблями и людьми. Делин помнил эту цену до конца своей жизни.]=],
		},
		{
			title = "Армада",
			text = [=[После {link:third-war}Третьей войны{/link} его дочь {link:jaina-proudmoore}Джайна{/link} повела уцелевших жителей {link:lordaeron}Лордерон{/link}а на запад, в {link:kalimdor}Калимдор{/link}, и построила {link:theramore-isle}город Терамор{/link}. Там она и {link:thrall}Тралл{/link} заключили мир. Делин не пожелал его признать. Он приплыл в Калимдор с большим флотом, возвел {link:tiragarde-keep}Крепость Тирагард{/link} на берегу {link:durotar}Дуротар{/link}а и пошел войной на {link:orcs}орк{/link}ов и на троллей Островов Эха. {link:horde}Орда{/link} ответила. Ее воины разбили крепость и наконец донесли бой до стен самого Терамора. Джайна отступила в сторону. В этом бою адмирал был убит.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он командовал флотом {link:kul-tiras}Кул Тирас{/link}а во Вторую войну.
• Он возвел {link:tiragarde-keep}Крепость Тирагард{/link} на берегах {link:durotar}Дуротар{/link}а.
• Он пошел войной на Орду вопреки миру, который заключила его дочь.
• Он оставил приказы для войны, которая должна была продолжиться после его смерти.]=],
		},
		{
			title = "Чего не сохранили летописи",
			text = [=[Здесь мало написано о том, как жил Делин до войн. Эта запись передает лишь то, что открывают предания и его собственные приказы.]=],
		},
	},
	chapters = {
		{
			title = "Приказы адмирала",
			hint = [=[Прочтите запечатанные приказы, которые хранятся в Крепости Тирагард.]=],
			text = [=[Среди вещей лейтенанта {link:archbishop-benedictus}Бенедикт{/link}а лежал старый конверт с печатью адмирала. В нем были приказы, написанные еще до того, как Делин покинул {link:kul-tiras}Кул Тирас{/link}. Они показывали, что он хорошо подготовил свои планы и что за первым флотом в {link:durotar}Дуротар{/link} должны были последовать новые его люди. {link:orcs}Орки{/link} Колючего Холма прочли в них простое предостережение: адмирал мертв, а его война — нет.]=],
		},
	},
	mentions = {
		{ text = "Покарать предателей" },
		{
			text = [=[Приказы адмирала, доставленные командиру {link:gar-thok}Гар'Ток{/link}у]=],
		},
		{
			text = [=[Приказы адмирала, доставленные в {link:orgrimmar}Оргриммар{/link}]=],
		},
	},
	bonds = {
		{ id = "jaina-proudmoore", name = "Джайна Праудмур", note = "его дочь" },
		{ id = "lieutenant-benedict", name = "лейтенант Бенедикт", note = "продолжает его войну" },
		{ id = "thrall", name = "Тралл", note = "его враг" },
	},
})
